window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-94d32dac0ce25dee"]={"versions": [{"id": "FIG-94d32dac0ce25dee", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Definition). Der architektonische Kontext umfasst die BSW-Kommunikationsschichten des CAN-Stacks (Communication Drivers / Hardware Abstraction Layer) und beschreibt die konfigurationsseitige Kopplung zwischen dem TTCAN-Treiber (<code>CanDrv</code>) und dem CAN-Interface (<code>CanIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>CanGeneral</code>: <code>EcucParamConfContainerDef</code> (Package <code>(from CanDrv)</code>), repräsentiert den allgemeinen Konfigurationscontainer des Treibers mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanSupportTTCANRef</code>: <code>EcucReferenceDef</code>, per Komposition (<code>+reference</code>) in <code>CanGeneral</code> eingebettet; weist eine gerichtete Assoziation (<code>+destination</code>) auf das Ziel <code>CanIfPrivateCfg</code> auf.</li>\n<li><code>CanIfPrivateCfg</code>: <code>EcucParamConfContainerDef</code> (Package <code>(from CanIf)</code>), Zielcontainer für private Konfigurationen des CAN-Interfaces.</li>\n<li><code>CanIfSupportTTCAN</code>: <code>EcucBooleanParamDef</code> (Package <code>(from CanIf_TT)</code>), per Komposition (<code>+parameter</code>) in <code>CanIfPrivateCfg</code> eingebettet; spezifiziert den Initialwert <code>defaultValue = FALSE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Laufzeitdynamik oder Sequenzablauf. Es modelliert die Entwurfs- und Generierungszeit (Pre-Compile): Konfiguriert die Abhängigkeit des Treibers zur Aktivierung der TTCAN-Unterstützung im übergeordneten CAN-Interface über eine typisierte Modellreferenz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Metamodellvorgabe für die Konfiguration des Moduls TTCAN-Treiber.</li>\n<li>Der Container <code>CanGeneral</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Die Referenz <code>CanSupportTTCANRef</code> erzwingt die konsistente Verknüpfung auf <code>CanIfPrivateCfg</code>.</li>\n<li><code>CanIfSupportTTCAN</code> ist standardmäßig deaktiviert (<code>defaultValue = FALSE</code>), wodurch TT-CAN-Unterstützung im CAN-Interface bei Bedarf explizit auf <code>TRUE</code> konfiguriert werden muss.</li>\n<li>Konfigurationswerkzeuge (ECU Configuration Editors / Code-Generatoren) müssen die referenzielle Integrität zwischen <code>CanDrv</code> und <code>CanIf</code> anhand dieser Modellbeziehung validieren.</li>\n</ul>"}, {"id": "FIG-bd194aa5a97d4f2a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC Parameter Definition). Der architektonische Kontext umfasst die BSW-Kommunikationsschichten des CAN-Stacks (Communication Drivers / Hardware Abstraction Layer) und beschreibt die konfigurationsseitige Kopplung zwischen dem TTCAN-Treiber (<code>CanDrv</code>) und dem CAN-Interface (<code>CanIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>CanGeneral</code>: <code>EcucParamConfContainerDef</code> (Package <code>(from CanDrv)</code>), repräsentiert den allgemeinen Konfigurationscontainer des Treibers mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanSupportTTCANRef</code>: <code>EcucReferenceDef</code>, per Komposition (<code>+reference</code>) in <code>CanGeneral</code> eingebettet; weist eine gerichtete Assoziation (<code>+destination</code>) auf das Ziel <code>CanIfPrivateCfg</code> auf.</li>\n<li><code>CanIfPrivateCfg</code>: <code>EcucParamConfContainerDef</code> (Package <code>(from CanIf)</code>), Zielcontainer für private Konfigurationen des CAN-Interfaces.</li>\n<li><code>CanIfSupportTTCAN</code>: <code>EcucBooleanParamDef</code> (Package <code>(from CanIf_TT)</code>), per Komposition (<code>+parameter</code>) in <code>CanIfPrivateCfg</code> eingebettet; spezifiziert den Initialwert <code>defaultValue = FALSE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Laufzeitdynamik oder Sequenzablauf. Es modelliert die Entwurfs- und Generierungszeit (Pre-Compile): Konfiguriert die Abhängigkeit des Treibers zur Aktivierung der TTCAN-Unterstützung im übergeordneten CAN-Interface über eine typisierte Modellreferenz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Metamodellvorgabe für die Konfiguration des Moduls TTCAN-Treiber.</li>\n<li>Der Container <code>CanGeneral</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Die Referenz <code>CanSupportTTCANRef</code> erzwingt die konsistente Verknüpfung auf <code>CanIfPrivateCfg</code>.</li>\n<li><code>CanIfSupportTTCAN</code> ist standardmäßig deaktiviert (<code>defaultValue = FALSE</code>), wodurch TT-CAN-Unterstützung im CAN-Interface bei Bedarf explizit auf <code>TRUE</code> konfiguriert werden muss.</li>\n<li>Konfigurationswerkzeuge (ECU Configuration Editors / Code-Generatoren) müssen die referenzielle Integrität zwischen <code>CanDrv</code> und <code>CanIf</code> anhand dieser Modellbeziehung validieren.</li>\n</ul>"}], "trans": [{"from": "FIG-94d32dac0ce25dee", "to": "FIG-bd194aa5a97d4f2a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
